var P={};

P['index']={title:'Wenn Zusammenarbeit über Ergebnisse entscheidet',nav:'',html:function(){return hero({k:'Für Geschäftsführungen im Mittelstand',h:'Wenn Zusammenarbeit über Ergebnisse entscheidet',l:'Wir begleiten Unternehmen dabei, Verantwortung dorthin zu bringen, wo die Arbeit passiert. Das verkürzt Entscheidungswege, nimmt Reibung aus Projekten und macht Teams wirksam, auch wenn KI und neue Vorgaben das Tempo erhöhen.',n:'Discovery Call heißt, eine Stunde auf eure Bedarfe schauen, gemeinsam mit uns, ohne Verkaufsdruck.',v:foto('9240',1200)})+
sec({h:'Mit diesen Organisationen arbeiten wir zusammen',b:logos()})+
sec({c:'alt',ill:'1060388229',h:'Wenn Entscheidungen zu lange dauern',i:'Viele Geschäftsführungen kennen das. Das Unternehmen ist gewachsen, die Strukturen sind es nicht. Jeder Monat, in dem das so bleibt, kostet Tempo, gute Leute und Nerven.',b:cards([{i:'entscheid',t:'Alles landet bei der Geschäftsführung',p:'Jede Rückfrage wandert nach oben. Das kostet Zeit, die für das Wesentliche fehlt.'},{i:'wirkung',t:'Gute Leute, zu wenig Wirkung',p:'Das Team könnte mehr, doch Zuständigkeiten sind unklar und Absprachen fallen durch.'},{i:'ausloeser',t:'Neue Anforderungen, alte Strukturen',p:'Vorgaben, Fachkräftemangel und KI verändern die Arbeit schneller, als die Organisation sich entwickeln kann.'}])+'<p class="aside">Oder ihr kommt über einen konkreten Anlass zu uns: <a href="themen.html">Alle Anlässe</a>.</p>'})+
sec({h:'Was sich für euch auszahlt',i:'Zusammenarbeit ist kein Zusatz. Sie entscheidet, wie schnell eure Organisation handelt und wie viel von eurer Planung im Alltag ankommt.',b:cards([{i:'entscheid',t:'Schneller entscheiden',p:'Entscheidungen fallen dort, wo das Wissen ist. Die Geschäftsführung gewinnt Zeit für Strategie.'},{i:'wirkung',t:'Weniger Reibung',p:'Klare Rollen und Absprachen sparen Rückfragen, Nacharbeit und Konflikte.'},{i:'ziel',t:'Teams, die liefern',p:'Projekte kommen ins Ziel und Veränderungen halten im Alltag.'}])+'<p class="aside">Wirkung machen wir sichtbar. Wir halten vorher fest, woran ihr den Erfolg erkennt, und schauen nachher gemeinsam darauf.</p>'})+
sec({h:'Drei Wege, wie wir zusammenarbeiten können',i:'Je nachdem, wo ihr ansetzen wollt. Die meisten starten mit einem Individual- oder Teamtraining.',b:cards([{f:'0195',tag:'Individuell',t:'Für Führungskräfte und Fachleute',p:'Selbstführung und Führung des eigenen Teams verbessern.',l:'loesungen.html#individuell',m:'Zu den Individual-Trainings'},{f:'9206',tag:'Team',t:'Für ganze Teams',p:'Gemeinsam besser entscheiden, mit KI arbeiten und Selbstorganisation üben.',l:'loesungen.html#teams',m:'Zu den Teamtrainings'},{f:'1443',tag:'Organisation',t:'Für das ganze Unternehmen',p:'Beratung, die mit einer Standortbestimmung startet.',l:'organisationen.html',m:'Mehr zur Beratung'}])+'<div class="kit">'+ic('ki')+'<div><h3>Das KI-Zeitalter denken wir mit</h3><p>KI gelingt im Team, nicht im Tool. Die Technik ist schnell eingeführt. Die eigentliche Arbeit beginnt bei Führung, Vertrauen und Zusammenarbeit.</p></div>'+a('Unsere Trainings zum Thema KI','ki-zeitalter.html')+'</div>'})+
sec({c:'alt',h:'Technik verändert sich schnell. Zukunftskompetenzen bleiben. Deshalb bauen alle unsere Angebote auf Future Skills auf.',b:'<div class="two fsrow"><div><p class="intro">Für jedes Training kombinieren wir passende Future Skills, die für die Arbeitswelt der Zukunft relevant sind. Das sind die Fähigkeiten, die Menschen und Teams brauchen, um mit Umbrüchen wie in Zeiten von KI gut zusammenzuarbeiten. Welche Future Skills für euch besonders wichtig sind, klären wir gemeinsam.</p></div>'+fsGraphic()+'</div><div style="margin-top:44px">'+modChips+'</div><p style="margin-top:30px">'+lnk('Mehr über die Future Skills','future-skills.html')+' &nbsp;&nbsp; '+lnk('Die Lösungen im Überblick','loesungen.html')+'</p>'})+
sec({h:'Was andere sagen',b:quotes()})+
sec({c:'alt',ill:'355007495',rev:true,h:'Unser Beratungsansatz',b:'<div class="two top"><div><p class="intro">Wir arbeiten iterativ. Wir schauen hin, setzen um, messen und lernen daraus, in Schleifen statt in einem großen Wurf.</p>'+steps(BER).replace('class="steps"','class="steps one"')+kibunBox()+'</div><div class="tall" style="position:sticky;top:96px">'+foto('1548',1000,'hoch')+'</div></div>'})+
sec({h:'Wer wir sind',b:'<div class="two"><div>'+foto('3678',1200)+'</div><div><p class="bigtxt">Wir sind ein Kollektiv aus drei Menschen, ein gleichwertiges Team von Unternehmerinnen und Unternehmern. Wir arbeiten selbst so, wie wir es in Teams anregen.</p><p style="margin-top:26px">'+lnk('Team kennenlernen','ueber-uns.html')+'</p></div></div>'})+
'<section class="sec dark"><div class="wrap two"><div><p class="kick">Teamcheck</p><h2>Wo steht euer Team gerade?</h2><p class="intro">Vier offene Fragen. Ihr bekommt von uns eine persönliche Einschätzung per Mail, kostenlos und ohne Verkaufsdruck.</p></div><div class="ctas" style="justify-content:flex-start">'+a('Zum Teamcheck','teamcheck.html','w')+'</div></div></section>'+
sec({h:'Ihr möchtet in Kontakt bleiben?',i:'Dann tragt euch in unseren Newsletter ein. Wir schreiben unregelmäßig und nur, wenn wir etwas zu sagen haben.',b:nl()+'<p class="aside">'+lnk('Frühere Ausgaben lesen','newsletter.html')+'</p>'})+
cta('Klärt, was euch das Warten kostet','Eine Stunde auf eure Bedarfe, gemeinsam mit uns. Danach wisst ihr, ob und wie wir euch helfen können.')}};

P['loesungen']={title:'Lösungen',nav:'loesungen.html',html:function(){return hero({k:'Unsere Lösungen',h:'Wo wollt ihr ansetzen?',l:'Gute Zusammenarbeit zahlt sich aus: schnellere Entscheidungen, weniger Reibung, Teams, die liefern. Ihr könnt bei einzelnen Personen, bei einem Team oder bei der ganzen Organisation ansetzen. Alle Lösungen bauen wir aus <a href="future-skills.html">Future Skills</a>, den Fähigkeiten, die Menschen und Teams für gute Zusammenarbeit brauchen.',c:BOOK+lnk('Erst selbst hinschauen: Teamcheck','teamcheck.html'),v:foto('1499',1200)})+
sec({h:'Wofür sich das für euch lohnt',i:'Auf jeder Ebene zahlt sich etwas anderes aus. Alle Lösungen starten mit einem Ziel, das ihr messen könnt.',b:cards([{i:'ich',t:'Einzelne: mehr Wirkung pro Arbeitstag',p:'Führungskräfte und Fachleute setzen klare Prioritäten und geben Orientierung. Das spart Zeit und Nerven.'},{i:'du',t:'Teams: weniger Reibung, mehr Tempo',p:'Klare Rollen und offenes Feedback verkürzen Abstimmungen und verhindern Nacharbeit.'},{i:'wir',t:'Organisation: Wandel, der im Alltag ankommt',p:'Veränderungen halten, weil Führung und Teams sie gemeinsam tragen.'}])+'<p class="aside">Wir halten vorher fest, woran ihr den Erfolg erkennt, und schauen nachher gemeinsam darauf.</p>'})+
'<span id="lesen"></span>'+sec({h:'So lest ihr unser Portfolio',i:'Wir arbeiten auf drei Ebenen. Jede hat einen Namen in Klartext und ein Kürzel, das ihr auf den Seiten wiederfindet.',b:cards([{i:'ich',tag:'FIT',t:'Future Individual Trainings',p:'Trainings für einzelne Personen. Sie stärken individuelle Future Skills, zum Beispiel Selbstführung. Eine beliebige Gruppe von Personen aus eurer Organisation kann teilnehmen.',l:'#individuell',m:'Zu den Trainings'},{i:'du',tag:'FTT',t:'Future Team Trainings',p:'Trainings für ein festes Team von 4 bis 12 Personen. Sie stärken gemeinsame Future Skills, zum Beispiel Rollen, Absprachen und Beziehungen.',l:'#teams',m:'Zu den Trainings'},{i:'wir',tag:'FOT',t:'Future Organisation Transformation',p:'Begleitung der ganzen Organisation, von Zweck über Struktur bis Kultur. Dafür kombinieren wir bedarfsorientiert Trainings aus den beiden anderen Ebenen.',l:'#organisation',m:'Zur Begleitung'}])+'<p class="note">Future Skills sind die Fähigkeiten, die Menschen und Teams brauchen, um in einer komplexen, schnellen Welt gut zusammenzuarbeiten. Mehr dazu weiter unten.</p>'})+
'<span id="individuell"></span>'+sec({ill:'355007495',h:'Für Einzelne: Future Individual Trainings (FIT)',c:'alt',i:'Persönlich wirksamer werden. Die Trainings stärken individuelle Future Skills. Es nehmen Personen aus eurer Organisation teil, sie müssen nicht im selben Team arbeiten.',b:cards([{i:'ziel',tag:'FIT',t:'Fokussiert zum Ziel',p:'Konzentriert arbeiten und das Wichtige zuerst tun.',l:'fokussiert-zum-ziel.html'},{i:'lead',tag:'FIT · denkt das KI-Zeitalter mit',t:'New Leadership: Führen im Zeitalter von KI',p:'Als Führungskraft Orientierung und Vertrauen geben, wenn KI die Arbeit verändert.',l:'new-leadership.html'}],'g2')})+
'<span id="teams"></span>'+sec({ill:'LTEAM',rev:true,h:'Für Teams: Future Team Trainings (FTT)',i:'Gemeinsam besser zusammenarbeiten. Die Trainings stärken gemeinsame Future Skills. Ein festes Team von 4 bis 12 Personen nimmt gemeinsam teil, am besten mit der Führungskraft.',b:cards([{i:'selbst',tag:'FTT',t:'Future Team: Wirksame Selbstorganisation',p:'Rollen, Entscheidungen und Absprachen im Team klären.',l:'selbstorganisation.html'},{i:'partner',tag:'FTT',t:'Future Team: Wertschätzende Beziehungen',p:'Feedback und Konflikte so gestalten, dass Beziehungen daran wachsen.',l:'wertschaetzende-beziehungen.html'},{i:'ki',tag:'FTT · denkt das KI-Zeitalter mit',t:'Future Team: Zusammenarbeit im Zeitalter von KI',p:'Wie KI im Team gelingt: mit Vertrauen, Neugier und der Bereitschaft, gemeinsam zu lernen',l:'zusammenarbeit-ki-zeitalter.html'}],'g3')})+
'<span id="organisation"></span>'+sec({ill:'LORG',h:'Für die Organisation: Future Organisation Transformation (FOT)',c:'alt',b:'<div class="two" style="margin-top:20px">'+foto('9315',1000)+'<div><p class="intro">Wir starten mit einer Standortbestimmung, zum Beispiel mit dem Discovery Call, Future Skills Check oder <a href="kibun.html">Kibun</a>, und schauen gemeinsam auf eure Bedarfe. Daraus entsteht die Begleitung für Teams, Rollen und Strukturen.</p><p>In der Leadership-Journey entwickelt das Führungsteam eine Vorbildfunktion für die gewünschte Kultur. So gelingt der Wandel in der ganzen Organisation glaubwürdig und nachhaltig.</p><p>'+a('Beratung ansehen','organisationen.html')+'</p></div></div>'})+
'<span id="ki"></span>'+sec({h:'Das KI-Zeitalter denken wir mit',i:'Zwei unserer Lösungen behandeln gezielt, was KI für Führung und Zusammenarbeit bedeutet. Dabei geht es nicht darum, im Training KI zu benutzen. Wir nehmen die Herausforderungen des KI-Zeitalters ernst: Verunsicherung, Vertrauen, Verantwortung.',b:'<p>'+a('Zum KI-Überblick','ki-zeitalter.html')+'</p>'})+
sec({ill:'L355877306',rev:true,h:'Future Skills, die kleinsten Einheiten',i:'Future Skills sind die Fähigkeiten, die Menschen und Teams brauchen, um in einer komplexen, schnellen und unvorhersehbaren Welt gut zusammenzuarbeiten und sich anzupassen. Wir unterscheiden drei Ebenen: Ich, Du und Wir. Jedes Training besteht aus Future Skills, ihr wählt mit uns aus, was ihr braucht. Neben den Standardtrainings gestalten wir individuelle Lösungen auf Basis der vier Quadranten und der Future Skills.',b:modChips+band('2659','Gemeinsam an echten Fragen arbeiten')+'<p>'+lnk('Mehr über die Future Skills','future-skills.html')+'</p><p class="note">Angelehnt an die Ebenen nach dem Future Skills Navigator. Platzhalter: Liste mit Franzi abgleichen, Dauer eines Bausteins ergänzen.</p>'})+
sec({h:'Euer Weg mit uns',c:'alt',i:'Von der ersten Begegnung bis zur Transformation. Ihr entscheidet bei jedem Schritt, ob und wie es weitergeht.',b:JR(CJ,['0369','1706','1682','1656','1790','0937'])})+
sec({h:'Wo Unternehmen gerade Druck spüren',b:cards([{i:'sicher',t:'NIS-2 und Rollenklarheit',p:'Verantwortung für Informationssicherheit braucht klare Rollen.',l:'anlass-nis2.html'},{i:'nachfolge',t:'Wenn der Betrieb am Chef hängt',p:'Unabhängiger werden von einzelnen Personen.',l:'anlass-nachfolge.html'},{i:'onboarding',t:'Onboarding, das trägt',p:'Neue Leute schneller wirksam machen.',l:'anlass-onboarding.html'}])})+
cta('Welcher Einstieg passt zu euch?','Das finden wir im Gespräch heraus.')}};

P['organisationen']={title:'Für Organisationen',nav:'loesungen.html',html:function(){return hero({k:'Beratung für Geschäftsführungen',h:'Wirksam zusammenarbeiten, im ganzen Unternehmen',l:'Wir starten mit einer Standortbestimmung, in der Geschäftsführung und Schlüsselpersonen gemeinsam klären, wo die Organisation heute steht und wohin sie soll.',v:foto('9117',1000)})+
sec({ill:'L1355018686',h:'Woran ihr merkt, dass es Zeit ist',c:'alt',b:cards([{i:'schritte',t:'Wachstum ohne Struktur',p:'Das Unternehmen ist größer geworden, die Absprachen sind geblieben, wie sie waren.'},{i:'entscheid',t:'Engpass Geschäftsführung',p:'Zu viele Entscheidungen laufen über wenige Köpfe.'},{i:'wirkung',t:'Veränderung ohne Wirkung',p:'Es gab Projekte und Programme, im Alltag hat sich wenig bewegt.'}])})+
sec({h:'Was Abwarten kostet',i:'Die Folgen zeigen sich selten an einem Tag. Sie summieren sich.',b:cards([{i:'entscheid',t:'Tempo',p:'Entscheidungen brauchen Wochen statt Tage. Aufträge, Chancen und gute Ideen gehen vorbei.'},{i:'ich',t:'Gute Leute',p:'Wer keine Wirkung sieht, geht. Eine Nachbesetzung kostet Zeit, Geld und Wissen.'},{i:'schritte',t:'Verpuffte Investitionen',p:'Programme ohne Wirkung binden Budget und Aufmerksamkeit, ohne dass sich im Alltag etwas ändert.'}])})+
sec({ill:'1060391264',rev:true,h:'Der Weg',b:steps([['Discovery Call','Wir lernen eure Lage kennen und prüfen, ob wir passen.'],['Standortbestimmung','Zum Beispiel mit dem Discovery Call, Future Skills Check oder <a href="kibun.html">Kibun</a>. Platzhalter: Dauer, Teilnehmende, Ergebnis. Am Ende habt ihr ein gemeinsames Bild und klare nächste Schritte.'],['Begleitung','Wir begleiten die Umsetzung in Teams und Rollen. Platzhalter: Formate wie Trainings, Coaching, Reviews.'],['Wirkung prüfen','Nach einem halben bis einem Jahr schauen wir mit denselben Methoden noch einmal hin und vergleichen mit dem Ausgangsbild. So seht ihr schwarz auf weiß, was sich verändert hat. Platzhalter: Zeitraum festlegen.']])+band('1138','Ein gemeinsames Bild entsteht an der Wand')})+
sec({c:'alt',h:'Kibun: Stimmung und Wirkung messbar machen',i:'Als Kibun Innovation Architects begleiten wir Organisationen mit Kibun, einer Plattform für regelmäßiges Feedback. Wir nutzen sie als Analysewerkzeug am Anfang und als laufende Rückmeldung zu unserer Arbeit. Das passiert nur, wenn ihr es wollt und die Organisation groß genug ist.',b:steps(KB)+'<p style="margin-top:22px">'+lnk('Mehr zu Kibun','kibun.html')+'</p>'})+
sec({h:'Die Bausteine, die wir dafür nutzen',b:modChips+'<p style="margin-top:22px">'+lnk('Alle Trainings ansehen','loesungen.html')+'</p>'})+
sec({c:'alt',h:'Platzhalter: Ein Beispiel aus der Praxis',b:quote('Platzhalter: Kurze Fallgeschichte in drei Sätzen. Ausgangslage, was wir getan haben, was sich verändert hat. Nur mit Freigabe des Kunden.','Platzhalter, Branche, Unternehmensgröße')})+
sec({h:'Häufige Fragen',b:faq([['Wie lange dauert die Standortbestimmung?','Platzhalter: Das hängt von Größe und Ziel ab. Wir klären es im Discovery Call.'],['Wer sollte dabei sein?','Platzhalter: Geschäftsführung und Personen, die Entscheidungen im Alltag tragen.'],['Was kostet das?','Das besprechen wir nach dem Discovery Call, wenn wir eure Lage kennen. Dort klären wir auch, was euch der jetzige Zustand kostet.']])})+
cta('Starten wir mit einem Gespräch','Im Discovery Call klären wir, was euch der jetzige Zustand kostet und welcher Einstieg sich für euch lohnt.')}};

P['kibun']={title:'Kibun',nav:'loesungen.html',html:function(){return hero({k:'Partner',h:'Kibun: Zusammenarbeit messbar machen',l:'Kibun ist eine Software-Plattform für regelmäßiges Feedback in Organisationen. Wir arbeiten eng mit Kibun zusammen und begleiten euch als Innovation Architects, damit aus Daten Veränderung wird.',c:BOOK+lnk('Zur Beratung für Organisationen','organisationen.html'),n:'<img src="'+KLOGO+'" alt="Kibun" style="max-height:64px;width:auto">',v:foto('9229',1000)})+
sec({c:'alt',ill:'L1355021830',h:'Was Kibun ist',i:'Statt einer jährlichen Befragung erfasst Kibun die Stimmung im Unternehmen laufend. Ein Dashboard zeigt Führung und Personalabteilung, wo es gut läuft und wo Handlungsbedarf entsteht.',b:steps(KB)})+
sec({h:'Wie wir Kibun nutzen',b:'<div class=\"two\" style=\"margin-top:20px\"><div>'+steps([['Als Analysewerkzeug','Zu Beginn zeigt Kibun gemeinsam mit unseren anderen Messungen, wo ihr steht. Die Daten sind die Grundlage für die Standortbestimmung und für das, was wir danach vorschlagen.'],['Als laufende Rückmeldung','Während unserer Arbeit zeigt Kibun, ob sich etwas verändert. So prüfen wir gemeinsam, ob unsere Maßnahmen wirken, und steuern nach.'],['Mit unserer Begleitung','Wir sind Kibun Innovation Architects und besprechen die Ergebnisse regelmäßig mit euch, damit daraus konkrete Schritte werden. Platzhalter: Format der Begleitung.']]).replace('class=\"steps\"','class=\"steps one\"')+'<p style=\"margin-top:20px\">'+BOOK+'</p></div>'+foto('0043',900)+'</div>'})+
sec({c:'alt',ill:'1060391264',rev:true,h:'Wann Kibun passt',b:cards([{t:'Ihr wollt es',p:'Kibun setzen wir nur ein, wenn ihr dahintersteht. Die Mitarbeitenden werden vorher informiert und beteiligt.'},{t:'Die Organisation ist groß genug',p:'Damit die Rückmeldungen anonym bleiben und aussagekräftig sind, braucht es eine gewisse Größe. Platzhalter: Richtwert nennen.'},{t:'Ihr wollt dranbleiben',p:'Kibun lohnt sich, wenn ihr aus den Ergebnissen Maßnahmen ableitet und ein Jahr lang mit uns schaut, was sich bewegt.'}])+'<p style=\"margin-top:24px\">'+BOOK+'</p>'})+
sec({h:'Datenschutz und Gefährdungsbeurteilung',b:cards([{t:'Anonym und in Deutschland gehostet',p:'Laut Kibun erfolgt die Befragung anonym, die Daten liegen auf Servern in Deutschland und das Verfahren ist DSGVO-konform. Platzhalter: Angaben mit Kibun abstimmen.'},{t:'Psychische Gefährdungsbeurteilung',p:'Die gesetzlich vorgeschriebene psychische Gefährdungsbeurteilung lässt sich über den 16-Wochen-Zyklus von Kibun mit Maßnahmen und Evaluation abdecken.'},{t:'Schnell sichtbare Wirkung',p:'Laut Kibun berichten 87 Prozent der Kunden schon nach sechs Wochen von positiven Auswirkungen. Platzhalter: Quelle und Stand prüfen.'}],'g3')})+
sec({c:'alt',h:'Platzhalter: Ein Beispiel aus der Praxis',b:quote('Platzhalter: Kurze Geschichte aus einem Kibun-Projekt, zum Beispiel Ausgangslage, Rücklaufquote, was sich verändert hat. Nur mit Freigabe des Kunden.','Platzhalter, Branche, Unternehmensgröße')})+
sec({h:'Häufige Fragen',b:faq([['Brauchen wir Kibun, um mit euch zu arbeiten?','Nein. Kibun ist ein Baustein unter mehreren. Wir arbeiten auch ohne, zum Beispiel mit dem Discovery Call oder Future Skills Check.'],['Was kostet Kibun?','Das besprechen wir im Gespräch, wenn wir eure Größe und euer Ziel kennen.'],['Wer sieht die Ergebnisse?','Platzhalter: Wer welche Auswertung sieht, mit Kibun und Datenschutz klären.'],['Ist Kibun ein Teil von EQ Collective?','Nein. Kibun ist ein eigenes Unternehmen. Wir sind Partner und arbeiten als Innovation Architects mit der Plattform.']])})+
cta('Wollt ihr wissen, wo ihr steht?','Im Discovery Call klären wir, ob eine Standortbestimmung mit Kibun für euch sinnvoll ist.')}};

P['fokussiert-zum-ziel']={title:'Fokussiert zum Ziel',desc:'Training für Einzelne: weniger Ablenkung, mehr Wirkung. Das Future Individual Training (FIT) von EQ Collective.',nav:'loesungen.html',html:produkt({k:'Training für Einzelne · Future Individual Training (FIT)',n:FITN,h:'Fokussiert zum Ziel',l:'Weniger Ablenkung, mehr Wirkung. Ihr lernt, den eigenen Arbeitstag so zu gestalten, dass das Wichtige Raum bekommt.',il:'1060391264',vor:['Ihr werdet ständig unterbrochen und kommt kaum zum Eigentlichen.','Dringendes verdrängt Wichtiges, Aufgaben bleiben liegen.','Der Tag endet mit dem Gefühl, viel getan und wenig bewegt zu haben.'],nach:['Ihr habt feste Blöcke für konzentrierte Arbeit.','Ihr setzt Prioritäten bewusst und sagt Nein, wenn es nötig ist.','Wichtige Aufgaben werden fertig, bevor sie dringend werden.'],mess:'Ihr legt vorher ein Ziel fest, zum Beispiel Stunden ungestörter Arbeit pro Woche oder erledigte Schlüsselaufgaben, und schaut nach dem Training gemeinsam, was sich bewegt hat.',il2:'355007495',nutzen:[{t:'Mehr tiefe Arbeitszeit',p:'Ihr schafft Blöcke, in denen ihr ungestört arbeiten könnt.'},{t:'Klare Prioritäten',p:'Ihr unterscheidet Dringendes von Wichtigem und sagt Nein, wenn es nötig ist.'},{t:'Gelassener im Alltag',p:'Ihr behaltet den Überblick, auch wenn viel auf einmal kommt.'}],fuer:'Für Führungskräfte und Fachleute, die ständig unterbrochen werden und das Gefühl haben, kaum zum Eigentlichen zu kommen. Platzhalter: Zielgruppe schärfen.',f2:'3527',ablauf:0,foto:'0053',cap:'Raum für konzentriertes Arbeiten',faq:[['Wie lange dauert das Training?','Platzhalter: Format und Dauer klären wir im Discovery Call.'],['Gibt es das auch für Gruppen?','Ja. Wir bauen es für Einzelne oder für mehrere Personen aus einem Unternehmen.'],['Müssen wir etwas vorbereiten?','Platzhalter: Vorbereitung.']]})};

P['new-leadership']={title:'New Leadership: Führen im Zeitalter von KI',nav:'loesungen.html',html:produkt({k:'Training für Einzelne · Future Individual Training (FIT)',n:FITN,h:'New Leadership: Führen im Zeitalter von KI',l:'KI verändert, was Führung leisten muss. Ihr stärkt die Fähigkeiten, die dabei wichtiger werden: Selbstführung, Beziehung und Orientierung für euer Team.',il:'1355017428',vor:['Führen heißt für euch vor allem Anweisen und Feuer löschen.','Euer Team wartet auf Entscheidungen, statt selbst Verantwortung zu übernehmen.','KI verunsichert, und ihr habt noch keine klare Haltung dazu.'],nach:['Ihr habt eine klare Führungsidentität und gebt Orientierung.','Euer Team übernimmt mehr Verantwortung und ihr werdet entlastet.','Ihr sprecht im Team offen über KI und Unsicherheit.'],mess:'Ihr haltet vor dem Training eure Selbsteinschätzung und die Rückmeldung eures Teams fest und schaut nach etwa drei Monaten noch einmal darauf. So seht ihr, ob Orientierung und Vertrauen gewachsen sind.',il2:'1060388229',wann:[['Das Tempo des Wandels überfordert','Das Tempo des Wandels übersteigt die Anpassungsfähigkeit vieler Führungskräfte.'],['KI verunsichert Teams','Viele fürchten um ihren Arbeitsplatz und fühlen sich von der Technik überfordert.'],['Unklare Spielregeln','Viele misstrauen KI-Entscheidungen und erleben unklare Verantwortung.']],ziel:'Ihr stärkt eure Selbstführung und euer Führungsverhalten, um Vertrauen und Orientierung zu stiften und euer Team im Zeitalter von KI sicher durch den Wandel zu steuern.',erg:['Gefestigte Führungsidentität, Selbstwirksamkeit und Werte, auch im KI-Kontext','Bewusstsein für eigene Stärken, um in Unsicherheit handlungsfähig zu bleiben','Fähigkeit, für das Team einen sicheren Beziehungsraum zu schaffen'],teiln:['Führungskräfte einer Organisation, die nicht als Team zusammenarbeiten müssen','Höchstens 12 Personen, ideal sind 8 bis 10','Begleitung durch Trainerinnen und Trainer von EQ Collective'],dauer:['Etwa 7 Wochen, davon 2 Tage in Präsenz (zweimal ein Tag)','Zwei Reflexionen remote zu je 90 Minuten','Ein Booklet mit Impulsen, Transfer und Notizen begleitet alle Wochen'],skills:['Selbstvertrauen &amp; Selbstwirksamkeit','Kommunikation &amp; Aktives Zuhören','Werteorientierung &amp; Authentizität','Beziehungsaufbau und -pflege','Inner Work &amp; Selbstreflexion','Psychologische Sicherheit','Anpassungsfähigkeit'],nutzen:[{t:'Klare eigene Rolle',p:'Ihr wisst, was ihr abgeben könnt und wo ihr gebraucht werdet.'},{t:'Bessere Gespräche',p:'Ihr führt Feedback und Konfliktgespräche, die weiterbringen.'},{t:'Ein Team, das Verantwortung übernimmt',p:'Ihr schafft Bedingungen, unter denen Menschen mitdenken.'}],fuer:'Für Führungskräfte, die merken, dass Anweisen nicht mehr reicht. Platzhalter: Zielgruppe schärfen.',f2:'3651',foto:'1481',cap:'Führung, die Menschen stärkt',abl:[['Modul 1: Selbstführung','Ein Tag in Präsenz. Ihr festigt Führungsidentität und Selbstwirksamkeit, um auch in dynamischen Situationen souverän und authentisch zu handeln.'],['Anwenden und reflektieren','Ihr probiert im Arbeitsalltag aus. Danach reflektiert ihr 90 Minuten remote gemeinsam.'],['Modul 2: Führungsverhalten','Ein Tag in Präsenz. Ihr stärkt Beziehung, Vertrauen und psychologische Sicherheit für euer Team.']],abln:'Eine Abschlussreflexion remote, 90 Minuten, sichert den Transfer. Platzhalter: Modulziel 2 mit Franzi abgleichen.',faq:[['Ist das nur für Geschäftsführungen?','Nein. Wir arbeiten auch mit Teamleitungen und Bereichsleitungen.'],['Gibt es Einzelbegleitung?','Platzhalter: Format klären.'],['Wie praxisnah ist das?','Ihr arbeitet an echten Situationen aus eurem Alltag. Platzhalter: Beispiele.']]})};

P['zusammenarbeit-ki-zeitalter']={title:'Zusammenarbeit im KI-Zeitalter',nav:'loesungen.html',html:produkt({k:'Training für Teams · Future Team Training (FTT)',n:FTTN,h:'Zusammenarbeit im KI-Zeitalter',l:'KI verändert, wie Teams arbeiten, entscheiden und einander vertrauen. Ihr klärt gemeinsam, was das für Rollen, Absprachen und Verantwortung bedeutet.',il:'1060394049',vor:['Jede Person nutzt KI auf eigene Faust, ohne gemeinsame Regeln.','Niemand weiß genau, wer Verantwortung trägt, wenn KI mitarbeitet.','Unsicherheit bremst, und Chancen bleiben liegen.'],nach:['Ihr habt gemeinsame Spielregeln für den Einsatz von KI.','Rollen und Verantwortung sind geklärt, auch dort, wo KI mithilft.','Das Team geht Neues mit Vertrauen an.'],mess:'Ihr haltet Regeln und Rollen schriftlich fest und prüft nach einigen Wochen im Team, ob sie im Alltag tragen.',il2:'1000339534',nutzen:[{t:'Ein gemeinsames Bild',p:'Ihr sprecht offen über Chancen, Sorgen und Unsicherheiten im Umgang mit KI.'},{t:'Klare Verantwortung',p:'Ihr klärt, wer was entscheidet und wofür ihr als Team steht, wenn KI mitarbeitet.'},{t:'Vertrauen im Team',p:'Ihr schafft psychologische Sicherheit, damit Neues ausprobiert und Fehler angesprochen werden.'}],fuer:'Für Teams, die merken, dass KI ihre Arbeit verändert, und das gemeinsam gestalten wollen. Platzhalter: Inhalte und Ablauf mit Franzi und Michi abgleichen.',f2:'9186',foto:'2407',cap:'Die Veränderung gemeinsam gestalten',faq:[['Müssen wir im Training KI benutzen?','Nein. Es geht darum, was KI für Zusammenarbeit, Verantwortung und Vertrauen im Team bedeutet. Vorkenntnisse braucht ihr nicht.'],['Wie lange dauert das Training?','Platzhalter: Format und Dauer klären wir im Discovery Call.'],['Passt das auch ohne eigene KI-Strategie?','Ja. Platzhalter: Aussage mit dem Team abstimmen.']]})};

P['wertschaetzende-beziehungen']={title:'Wertschätzende Beziehungen',nav:'loesungen.html',html:produkt({k:'Training für Teams · Future Team Training (FTT)',n:FTTN,h:'Wertschätzende Beziehungen',l:'Teams, die Feedback geben und konstruktiv mit Konflikten umgehen. Ihr stärkt Beziehungen, statt sie in schwierigen Momenten zu belasten.',il:'L355516285',vor:['Feedback bleibt aus oder kommt zu spät.','Konflikte schwelen und kosten Energie.','Gute Leute ziehen sich zurück oder gehen.'],nach:['Ihr gebt und nehmt Feedback offen, zeitnah und respektvoll.','Konflikte werden früh angesprochen und geklärt.','Das Team arbeitet mit mehr Vertrauen und Bindung.'],mess:'Ihr vergleicht vor und nach dem Training, wie das Team Zusammenarbeit, Feedback und Vertrauen einschätzt, zum Beispiel mit einer kurzen Teamumfrage.',il2:'355007495',nutzen:[{t:'Feedback, das ankommt',p:'Ihr lernt, Rückmeldungen so zu geben und anzunehmen, dass sie weiterbringen.'},{t:'Konflikte als Chance',p:'Ihr geht Spannungen früh an und löst sie, bevor sie das Team bremsen.'},{t:'Mehr Vertrauen',p:'Ihr baut Beziehungen auf, die auch dann tragen, wenn es schwierig wird.'}],fuer:'Für Teams, in denen Feedback selten gelingt oder Spannungen liegen bleiben. Platzhalter: Zielgruppe schärfen und Inhalte mit Franzi abgleichen.',f2:'3690',foto:'1195',cap:'Beziehungen wachsen im Gespräch',faq:[['Ist das ein Konflikttraining?','Auch. Es geht um Feedback- und Konfliktkompetenz, damit Beziehungen wertschätzend bleiben. Platzhalter: Abgrenzung schärfen.'],['Wie lange dauert das Training?','Platzhalter: Format und Dauer klären wir im Discovery Call.'],['Muss das ganze Team dabei sein?','Ja, es wirkt am besten mit allen Teammitgliedern. Platzhalter: Aussage prüfen.']]})};

