/* Future Skills: Erklärungen aus dem Miro-Katalog, "Warum es zählt" aus dem New-Leadership-Entwurf */
var FSD={
'Selbstvertrauen & Selbstwirksamkeit':['Die Überzeugung, neue oder schwierige Situationen aus eigener Kraft bewältigen zu können, und das Gefühl, mit Schwierigkeiten fertigzuwerden.','KI verändert die Anforderungen an die eigenen Kompetenzen. Selbstwirksamkeit hilft, handlungsfähig zu bleiben.'],
'Werteorientierung & Authentizität':['Die eigenen Werte und Glaubenssätze kennen, ihnen treu bleiben und danach handeln, auch unter Druck. Inneres Erleben und äußeres Handeln stimmen überein.','Feste Werte geben dem Team Kontinuität in einer Welt, die sich durch KI noch schneller wandelt.'],
'Inner Work & Selbstreflexion':['Die eigene innere Haltung erforschen und weiterentwickeln, das eigene Denken, Fühlen und Handeln hinterfragen.','Ein geklärtes Inneres schafft Authentizität und emotionale Stabilität, um dem Team im Wandel Halt zu geben.'],
'Introspektion und Selbsterkenntnis':['Den momentanen und den generellen emotionalen Zustand erfassen und erkennen, wie er sich verbessern lässt.',''],
'Anpassungsfähigkeit':['Flexibel auf Veränderungen reagieren, als Person und als Team oder Organisation, die Struktur und Regeln aus sich heraus weiterentwickelt.','KI beschleunigt Dynamiken. Gefragt ist eine Kultur, die das Ausprobieren von Neuem fördert.'],
'Kommunikation & Aktives Zuhören':['Neben der Sachebene auch Absichten, Bedenken und Emotionen des Gegenübers aufnehmen, validieren und spiegeln.','Je mehr Technologie Einzug hält, desto wichtiger wird, wer zuhört und Ängste nimmt.'],
'Beziehungsaufbau und -pflege':['Durch ehrliches Interesse und Offenheit tragfähige, respektvolle Arbeitsbeziehungen aufbauen und dauerhaft pflegen.','Vertrauen ist die Basis, damit Sorgen offen angesprochen werden und das Team den Wandel mitträgt.'],
'Psychologische Sicherheit':['Die gemeinsame Überzeugung, im Team zwischenmenschliche Risiken eingehen zu können: Ideen einbringen, kritisieren, Fehler zugeben, ohne Nachteile zu fürchten.','KI erfordert Experimentieren und kritisches Prüfen. Das gelingt nur ohne Angst vor Fehlern.'],
'Begleitung und Moderation':['Dafür sorgen, dass Teams effektiv arbeiten und Ziele erreichen, indem Teamdynamiken gestaltet und Bedarfe in Einklang gebracht werden.',''],
'Entscheidungsfindung':['Mutig Verantwortung übernehmen, Interessen abwägen sowie Entscheidungen zeitnah treffen und kommunizieren.',''],
'Projekt- und Ressourcenmanagement':['Situativ Teams zusammenstellen, mit den nötigen Ressourcen und Kompetenzen ausstatten und Prozesse an die Gegebenheiten anpassen.',''],
'Vision und Langzeitorientierung':['Das große Ziel einer Organisation erkennen und alle Handlungen konsequent daran ausrichten.',''],
'Kollaboration und Teamarbeit':['Unterschiedliche Teammitglieder durch das Nutzen von Synergien und eine positive Teamkultur zur Zusammenarbeit befähigen.',''],
'Co-kreatives Problemlösen':['Bedeutsame Probleme erkennen und gemeinsam neue, relevante Lösungen dafür finden.',''],
'Systemdenken und Kybernetik':['Situationen und Informationen in ihrem Kontext bewerten und im Sinne des großen Ganzen handeln.',''],
'Komplexitäts- und Ambiguitätstoleranz':['Souverän und sicher in einem komplexen, uneindeutigen Umfeld handeln.',''],
'Kritisches Denken und Hinterfragen':['Annahmen hinterfragen sowie Fakten, Beobachtungen und Argumente prüfen, um zu fundierten Entscheidungen zu kommen.',''],
'Verantwortungsbewusstsein':['Für das Allgemeinwohl sorgen, der Verantwortung zum Handeln nachkommen und die Konsequenzen des eigenen Handelns tragen.',''],
'Strategie und Umsetzung':['Ein abstraktes Ziel durch definierte Schritte in konkretes Handeln überführen und aus einer Vision eine Strategie ableiten.',''],
'Führen und Folgen':['Andere aktiv wahrnehmen und führen und je nach Situation und Kompetenz selbst folgen können.',''],
'Identität und Zugehörigkeit':['Bindung und ein Gefühl von Zugehörigkeit in Teams schaffen, das für die Mitglieder identitätsstiftend sein kann.',''],
'Aufrichtigkeit und Vertrauen':['Bei Gedanken und Absichten transparent und aufrichtig sein und so Beziehungen aufbauen, die auf gegenseitigem Vertrauen beruhen.',''],
'Konfliktbewältigung':['Konflikte akzeptieren, bewältigen und als Chance nutzen.',''],
'Momentum schaffen und Mitstreiter:innen finden':['Andere unter einer gemeinsamen Mission vereinen und ihre Wirkmacht freisetzen, damit sie gemeinsam handeln.',''],
'Neugier, Kreativität und Experimentierfreude':['Entdeckergeist wecken und Experimente und Misserfolge als Lernchancen begreifen.',''],
'Organisationsentwicklung':['Die Organisation so aufstellen, dass sie auch in einem instabilen Umfeld langfristig erfolgreich ist.','']
};
