P['call']={title:'Call vereinbaren',desc:'Wie wollt ihr starten? Coffee Call oder Discovery Call mit EQ Collective aus Rosenheim, persönlich und unverbindlich.',nav:'',html:function(){return hero({k:'Call vereinbaren',h:'Wie wollt ihr starten?',l:'Am liebsten sprechen wir persönlich mit euch. Wählt den Einstieg, der gerade passt.',c:'',v:foto('0589',900)})+
sec({c:'alt',b:'<div class="grid g2 callg"><div class="lbox t2">'+ic('coffee')+'<span class="tag">15 Minuten</span><h3>Coffee Call</h3><p>Ihr wollt uns erst kennenlernen oder habt eine Frage? Sprecht 15 Minuten mit uns, ohne Agenda und ohne Verkaufsdruck.</p><p>'+a('Coffee Call buchen','coffee-call.html','out')+'</p></div><div class="lbox t3">'+ic('call')+'<span class="tag">Eine Stunde</span><h3>Discovery Call</h3><p>Ihr habt ein konkretes Thema? Wir schauen gemeinsam auf eure Bedarfe und sagen euch ehrlich, ob und wie wir helfen können.</p><p>'+a('Discovery Call buchen','discovery-call.html')+'</p></div></div><p class="aside">Ihr wollt erst selbst hinschauen? '+lnk('Zum Teamcheck','teamcheck.html')+' Oder schreibt uns an <a href="mailto:aloha@eq-collective.de">aloha@eq-collective.de</a>, <a href="tel:+4916099340307">+49 (0) 160 99 34 03 07</a>.</p>'})+
sec({h:'Häufige Fragen',b:faq([['Was kostet ein Gespräch?','Nichts. Beides sind unsere Einstiege.'],['Was ist der Unterschied?','Der Coffee Call ist kurz und locker zum Kennenlernen. Im Discovery Call schauen wir eine Stunde auf eure Bedarfe.'],['Wer ist dabei?','Mindestens eine Person von uns und ihr. Platzhalter: Wer wann.']])})}};

