P['selbstorganisation']={title:'Wirksame Selbstorganisation',nav:'loesungen.html',html:loesung({k:'Lösung für Teams · Future Team Training',h:'Wirksame Selbstorganisation',l:'Teams, die ihre Arbeit selbst steuern. Ihr klärt Purpose, Rollen und Meetings, damit nicht alles bei einer Person hängt und das Team sich eigenständig weiterentwickelt.',il:'355007495',
hi:'Viele Teams arbeiten in der Praxis schon eigenständig, die Strukturen um sie herum sind es noch nicht. Typische Ausgangslagen:',
wann:[['Formal hierarchisch, gelebt selbstorganisiert','Das Team arbeitet in der Praxis vernetzt und eigenständig, die formalen Strukturen sind trotzdem hierarchisch.'],['Überlastung durch ständige Neuerungen','Eine hohe Aufgabenlast und neue Anforderungen führen zu Überlastung im Team.'],['Keine geteilte Vision, keine festen Meetings','Es fehlen oft ausdrückliche Ziele und feste Meeting-Strukturen.']],
li:'Euer Team arbeitet purpose-, rollen- und spannungsbasiert und nutzt strukturierte Meeting-Formate, um effektiver zusammenzuarbeiten. So passt es seine Arbeitsweise kontinuierlich und eigenständig an neue Anforderungen an. In drei Bausteinen bekommt ihr Klarheit, Rhythmus und Eigenständigkeit.',
mods:[{tag:'Baustein 1 · Training',t:'Klarheit: Purpose, Rollen, Spannungen',ziel:'Ihr formuliert einen gemeinsamen Team-Purpose, vereinbart Rollen mit klaren Verantwortungsbereichen und Erwartungen und lernt die vier Räume kennen, um Spannungen frühzeitig zu verarbeiten.',skills:['Vision und Langzeitorientierung','Projekt- und Ressourcenmanagement','Introspektion und Selbsterkenntnis']},{tag:'Baustein 2 · Training',t:'Rhythmus: Meetings und Entscheidungen',ziel:'Ihr lernt eine Meetingroutine für die operative Synchronisation und eine für die Weiterentwicklung der Struktur mit kollektiven Entscheidungsmethoden kennen und reflektiert eure bisherigen Meetings.',skills:['Kollaboration und Teamarbeit','Entscheidungsfindung','Anpassungsfähigkeit']},{tag:'Baustein 3 · Begleitung',t:'Eigenständigkeit: Meeting-Begleitung',ziel:'Eure Facilitatoren führen das Sync-Meeting und das Governance-Meeting selbst durch, wir begleiten die ersten Meetings und geben Feedback. Danach wendet das Team die neue Arbeitsweise im Alltag an.',skills:['Begleitung und Moderation','Anpassungsfähigkeit']}],
facts:[['Dauer','2,5 Tage plus Begleitung','2 Tage Präsenz und 0,5 Tage remote, danach Begleitung eurer Meetings','schritte'],['Lernformat','Blended','Präsenz und remote','call'],['Teilnehmende','Das ganze Team','Die Führungskraft und alle Teammitglieder','partner'],['Begleitung','Trainerinnen und Trainer von EQ Collective','inhouse, Investition im Gespräch','ich']],
abl:[['Tag 1 und 2 in Präsenz','Purpose, Rollen, die vier Räume, Meetingroutinen und Methoden zur Entscheidungsfindung. Wir arbeiten an euren echten Themen.'],['Tag 3 remote','Ein halber Tag zum Reflektieren und Nachschärfen eurer Meeting-Routinen. Platzhalter: Zeitpunkt im Ablauf.'],['Meeting-Begleitung','Wir begleiten euer Sync- und euer Governance-Meeting und geben Feedback, bis eure Facilitatoren es selbst tragen. Platzhalter: Anzahl und Abstand der Termine.']],
ziel:'Euer Team arbeitet purpose-, rollen- und spannungsbasiert zusammen, trifft viele Entscheidungen selbst und die Führungskraft gewinnt Zeit für das Wesentliche.',
erg:['Ein gemeinsamer Team-Purpose und klar vereinbarte Rollen','Meetingformate, die das Team selbst moderiert','Ein Team, das seine Arbeitsweise eigenständig weiterentwickelt'],
mess:'Ihr zählt vorher und nachher, wie viele Entscheidungen noch nach oben wandern und wie oft Absprachen nicht gehalten werden, und schaut gemeinsam auf den Unterschied.',
anl:['anlass-iso9001','anlass-nis2','anlass-nachfolge'],
faq:[['Heißt das, es gibt keine Führung mehr?','Nein. Führung bekommt eine andere Rolle. Wir klären sie mit euch.'],['Wer sollte dabei sein?','Die Führungskraft und alle Teammitglieder.'],FQB,['Passt das zu unserem Unternehmen?','Das prüfen wir im Discovery Call.'],FQA]})};

P['wertschaetzende-beziehungen']={title:'Wertschätzende Beziehungen',nav:'loesungen.html',html:loesung({k:'Lösung für Teams · Future Team Training',h:'Wertschätzende Beziehungen',l:'Teams, die Feedback geben und konstruktiv mit Konflikten umgehen. Ihr stärkt Beziehungen, statt sie in schwierigen Momenten zu belasten.',il:'L355516285',
hi:'So erleben wir es oft in Teams:',vor:['Feedback bleibt aus oder kommt zu spät.','Konflikte schwelen und kosten Energie.','Gute Leute ziehen sich zurück oder gehen.'],
li:'Das Team stärkt seine Feedback- und Konfliktkompetenz, um Beziehungen wertschätzend zu gestalten und Konflikte konstruktiv zu lösen. Im Training übt ihr an echten Situationen, danach begleiten wir euer erstes People Meeting, in dem ihr schwierige Themen besprecht und Wertschätzung ausdrückt.',
mods:[{tag:'Baustein 1 · Training',t:'Feedback geben und nehmen',ziel:'Ihr versteht, wozu Feedback da ist und wie es sich von Konflikten unterscheidet, lernt die vier Räume als Handlungsoptionen kennen und übt ein Feedback-Format.',skills:['Introspektion und Selbsterkenntnis','Kommunikation & Aktives Zuhören']},{tag:'Baustein 2 · Training',t:'Konflikte klären',ziel:'Ihr erkennt den Zusammenhang zwischen Bedürfnissen, Strategien und Konflikten, lernt die vier Schritte der Gewaltfreien Kommunikation und bereitet ein klärendes Gespräch an eigenem Beispiel vor.',skills:['Konfliktbewältigung','Empathie und Mitgefühl','Introspektion und Selbsterkenntnis']},{tag:'Baustein 3 · Training und Begleitung',t:'People Meeting: Beziehungsraum im Team',ziel:'Ihr probiert ein Meetingformat aus, mit dem das Team schwierige Themen bespricht und Wertschätzung ausdrückt, und legt eine feste Routine dafür fest. Wir begleiten eure People Meetings.',skills:['Psychologische Sicherheit','Bescheidenheit und Wertschätzung']}],
facts:[['Dauer','ca. 6 Wochen','2 Trainingstage in Präsenz (etwa 14 Stunden) und zwei begleitete People Meetings','schritte'],['Lernformat','Präsenz','Training bei euch im Haus oder in unserem Trainingsraum in Rosenheim, Begleitung der People Meetings','call'],['Teilnehmende','Das ganze Team','Die Führungskraft und alle Teammitglieder','partner'],['Begleitung','Trainerinnen und Trainer von EQ Collective','inhouse, Investition im Gespräch','ich']],
wt:'Euer Weg in 6 Wochen',weeks:[['Woche 1','Training','2 Tage Präsenz: Feedback, Bedürfnisse, Konflikte, People Meeting','m'],['Woche 2','People Meeting','Begleitet, 90 Minuten','r'],['Woche 3','Anwenden','im Arbeitsalltag','a'],['Woche 4','Anwenden','im Arbeitsalltag','a'],['Woche 5','Anwenden','im Arbeitsalltag','a'],['Woche 6','People Meeting','Begleitet, 90 Minuten','r']],wn:'Platzhalter: Abstände und Anzahl der Termine im Ablauf mit Franzi und Michi abstimmen.',
ziel:'Das Team arbeitet mit mehr Vertrauen und Bindung, weil Feedback und Konflikte früh und respektvoll zur Sprache kommen.',
erg:['Ihr gebt und nehmt Feedback offen, zeitnah und respektvoll','Konflikte werden früh angesprochen und geklärt','Das Team hat eine feste Routine für Wertschätzung und schwierige Themen'],
mess:'Ihr vergleicht vor und nach dem Training, wie das Team Zusammenarbeit, Feedback und Vertrauen einschätzt, zum Beispiel mit einer kurzen Teamumfrage.',
anl:['anlass-onboarding','anlass-iso9001','anlass-nis2'],
faq:[['Ist das ein Konflikttraining?','Auch. Es geht um Feedback- und Konfliktkompetenz, damit Beziehungen wertschätzend bleiben.'],['Muss das ganze Team dabei sein?','Ja, es wirkt am besten mit allen Teammitgliedern.'],FQB,FQA]})};

