function sn(s){return s.replace(/\s+/g,' ').trim()}
function Q(d,sel,txt){var l=d.querySelectorAll(sel);if(txt===undefined)return l[0]||null;for(var i=0;i<l.length;i++){if(sn(l[i].textContent).indexOf(txt)===0)return l[i]}for(var j=0;j<l.length;j++){if(sn(l[j].textContent).indexOf(txt)>-1)return l[j]}return null}
function miss(w){V6LOG.push(w)}
