function R(d,sel,txt){var e=Q(d,sel,txt);if(!e){miss('R '+sel+' '+txt);return null}e.parentNode.removeChild(e);return e}
function SE(d,txt){var h=Q(d,'section h2',txt);if(!h){miss('SE '+txt);return null}return h.closest('section')}
function RS(d,txt){var s=SE(d,txt);if(s)s.parentNode.removeChild(s);return s}
