function TX(d,from,to){var w=document.createTreeWalker(d,NodeFilter.SHOW_TEXT,null),n,c=0;while(n=w.nextNode()){if(n.nodeValue.indexOf(from)>-1){n.nodeValue=n.nodeValue.split(from).join(to);c++}}if(!c)miss('TX '+from);return c}
