(function(){var M={'index':[null,'EQ Collective aus Rosenheim begleitet Geschäftsführungen und Teams im Mittelstand: Training und Organisationsentwicklung für klare Rollen.'],'wertschaetzende-beziehungen':['Wertschätzende Beziehungen: Feedback im Team',null],'anlass-onboarding':['Onboarding: neue Leute schneller wirksam',null],'anlass-iso9001':['ISO 9001: ein System, das gelebt wird',null],'anlass-digitale-souveraenitaet':['Digitale Souveränität im Team gestalten',null],'agb':[null,'Allgemeine Geschäftsbedingungen von EQ Collective für Trainings, Workshops und Beratung in Rosenheim.']};Object.keys(M).forEach(function(k){if(!P[k])return;if(M[k][0])P[k].title=M[k][0];if(M[k][1])P[k].desc=M[k][1]})})();
